function detail(id){const e=state.events.find(e=>e.id===id);if(!e)return;openDialog('Request details',`<dl class="detail-list">${[['Request ID',e.id],['Time',new Date(e.time).toLocaleString('en-US')],['Client-IP',e.client],['Country',e.country||'—'],['Domain',e.host],['Route',e.route||'—'],['Method',e.method],['Path',e.path],['Status',e.status],['Duration',`${e.duration.toFixed(2)} ms`],['Reason',e.reason||'No rule match'],['CRS rules',e.ruleIds.join(', ')||'—']].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><div class="info">Payloads and query strings are not logged to protect sensitive data.</div>`,null);}
$('#main').addEventListener('click',async e=>{const el=e.target.closest('button,[data-event]');if(!el)return;try{if(el.dataset.jump){const target=document.getElementById(el.dataset.jump);target?.scrollIntoView({behavior:'auto',block:'start'});target?.querySelector('input,select,textarea')?.focus({preventScroll:true});}if(el.hasAttribute('data-event-action')){state.action=state.action===el.dataset.eventAction?'':el.dataset.eventAction;state.eventPage=0;$('#event-filter').value=state.action;updateEventTable();}if(el.hasAttribute('data-add-route'))routeEditor();if(el.dataset.editRoute)routeEditor(el.dataset.editRoute);if(el.hasAttribute('data-add-rule'))ruleEditor();if(el.dataset.editRule)ruleEditor(el.dataset.editRule);if(el.dataset.event)detail(el.dataset.event);if(el.dataset.toggleRoute){el.disabled=true;const next=clone(),r=next.routes.find(r=>r.id===el.dataset.toggleRoute);r.enabled=!r.enabled;await saveConfig(next);render();}for(const [key,collection,label] of [['deleteRoute','routes','Proxy Host'],['deleteRule','rules','Rule']]){if(el.dataset[key]){const id=el.dataset[key],item=state.config[collection].find(r=>r.id===id);openDialog(`${label} delete?`,`<p>„${esc(item.name)}“ will be removed from the configuration.</p>`,async()=>{const next=clone();next[collection]=next[collection].filter(r=>r.id!==id);await saveConfig(next);},'Delete');}}}catch(err){toast(err.message,true);el.disabled=false;}});
