async function poll(){if(!state.ready||document.hidden||state.polling)return;state.polling=true;try{const [status,events,analytics,upstreams]=await Promise.all([api('/api/status'),api('/api/events'),api('/api/analytics'),api('/api/upstreams')]);if(!state.ready)return;state.status=status;if(!state.eventsPaused&&!$('#editor').open&&!document.activeElement?.closest('[data-event]'))state.events=events;state.analytics=analytics;state.upstreams=upstreams;if(state.page==='tls')await refreshCertificates();$('#connection').classList.remove('offline');$('#connection').innerHTML='<span class="status-dot"></span> Connected';$('#updated').textContent=`Updated at ${time(Date.now())}`;if(state.page==='overview'&&!$('#editor').open)render();else if(!state.eventsPaused&&!$('#editor').open&&!document.activeElement?.closest('[data-event]'))updateEventTable();}catch(err){$('#connection').classList.add('offline');$('#connection').innerHTML='<span class="status-dot"></span> Connection interrupted';}finally{state.polling=false;}}
setInterval(poll,5000);
